          "passage": "A little boy named Frank liked large animals in storybooks but showed no interest in small ones in\nnature. He thought that insects were too small to be interesting, so he n 71 paid attention to small\nlives in the wild.\nOne summer morning, Frank's mother took him to a quiet field and asked him to watch insects\nc 72 and patiently. At first, Frank only saw stones, dry leaves and flowers. Then he saw a small\ninsect carrying something on the ground. It seemed to be moving with a clear purpose, slowing down\nnow and then as if it was checking the road. Frank wanted to pick it up, but his mother s 73 him.\n\"A good observer does not disturb,\" she said. Her w 74 deeply influenced Frank.\nThat morning, he stayed where he was, watching what was happening for nearly half an hour. He\nn 75 that the insect climbed over a stick, went around a hole and finally disappeared under a leaf.\nFrank began to wonder how such a small body could find its way. He opened his notebook and made\na simple drawing of the way.\nFrom that day on, Frank returned to the field each morning, observing quietly. Sometimes\nn 76 happened for a long time, but he still stayed patient.\nSlowly, the field became a living book for Frank. Every ant, bee and butterfly seemed to have its\nown story. Frank got to understand that nature was not b 77 . It was full of interesting things,\nwaiting for eyes to discover them.",
          "completionSource": {
            "checkedAt": "2026-10-10",
            "sourceSha256": "568d5ea2c38be68fb68d36049601b53e6dd238b6c8e4b1af683b7a3663d7f746"
          }
