          "id": "sh2026-q78",
          "originalNo": 78,
          "type": "open",
          "category": "阅读简答",
          "stem": "Is there a shop assistant at Honesty Corner?",
          "answer": "No, there isn’t.",
          "explanation": null,
          "review": {
            "status": "pending"
          },
          "passage": "In the Sunny Garden community centre, there’s a special place called \"Honesty Corner”. It is a small\nstall where people can buy food and drink. What makes it special is that there is no shop assistant.\nWhen paying, people just put money into a small box. Everything depends on trust.\nThe idea came from Mr Li. head of the community He believed that honesty should be practised in\ndaily life.\nIn the beginning, some people were worried. They thought someone might take things without\npaying, especially when no one was watching. In the first week, there were indeed a few missing\npayments. But the community didn't punish anyone. Instead, they trusted people would do the right\nthing.\nSlowly, things began to change. People started reminding each other to pay. Some even left notes\nlike “____________________________”. After several months, the situation improved. One resident,\nMs Zhang, even shared her story online:\nYesterday I forgot to bring money, but I still took a drink from Honesty Corner. Soon I felt worried\nand couldn’t focus at work all day. This morning, I went back and paid for it. After that I finally felt\nrelaxed.\nHer post got many \"likes\". More people began to think about their own behaviours and realise the\nimportance of Honesty Corner.",
          "completionSource": {
            "checkedAt": "2026-10-10",
            "sourceSha256": "568d5ea2c38be68fb68d36049601b53e6dd238b6c8e4b1af683b7a3663d7f746"
          }
