          "passage": "with proper words(在短文的空格内填入适当的词，使其内容通顺，每空\n格限填一词，首字母已给)（14 分） \n“Meatballs again?I hate meatballs!” Henry cried loudly. “I’m not eating this! ” Henry’s mum \nand dad looked at each other.This was the second time this week that Henry had c  81   about his \ndinner. \n“We’re going to let you take over dinnertime.You can pick the food and cook your meals, ” \nMum said. \n“Good.We’re going to eat good food every night!” Henry answered. \nThe next day,Henry sat down to write the meal p  82  . “We’re going to have chicken \ntonight,and noodles tomorrow,” Henry said. \n“Are we going to have anything e  83   besides chicken?We need to have at least one \nvegetable for each meal,”,said Mum. \n“We can have cabbage,”Henry said. \nAfter he finished shopping,it was time to make his f  84   meal.He believed that this would \nbe his favourite meal.Since he had never cooked,his parents were both there to help him. “There’s \na lot to do, ”Henry thought,as he looked at the mess in the kitchen.He was usually playing games \noutside while his parents were making dinner. \nIt took almost two hours to cook.When dinner was finally finished,Henry was tired and  \n\nh  85  .But he was so excited-he made dinner! \n“I don’t like cabbage,” cried Sophia,Henry’s little sister,at the table.Henry felt quite upset.He \nhad worked so hard on dinner,but it was i  86   to get everyone happy about every part of every \nmeal! \n“I’m sorry.I didn’t know this could be so hard,” Henry felt like he might cry.He began to  \nr  87   how his parents felt every time at the dinner table. \n“It’s OK,Henry.You worked really hard.We’ll take back dinner responsibilities.You’ll have to \ndo it enough when you’re grown up,”Dad said. \nHenry felt released.He happily finished his dinner and never got angry at dinner table again.",
