          "stem": "Write at least 60 words according to the given information（根据以下材料，写一篇不少于60个词的短文，标点符号不占格）\n以下是几位同学在以貌取人、盲从朋友、看待谎言、抉择人生等方面的感悟。请从中选择你比较有感触的一条，可结合自己的经历，谈谈你的体会。\nDon't judge people by their looks. Someone could be bad-looking and still be nice. —Katie\nWhen your friends do something stupid，you don't have to follow.—Jackie\nDon't tell a teacher your dog ate your homework，especially if you don't have a dog.—Alex\nLife is like a“choose your own ending” book-you can take whatever adventures you want.\n—Sally\n                                                                                                     \n                                                                                                \n___________________________________________________________________________                            \n(注意: 1. 先将你选择的一条感悟抄写在答题纸带有引号的横线上。)",
          "answer": "例文\nDon’t Judge a Book by Its Cover by Michelle As an old saying goes, don’t judge a book by its cover. I didn’t recognize the true meaning of it until last year. In my neighborhood came a man with a scary face. The first several times I came across him, I always ran away quickly, with hands covering my eyes. Later, I knew from my parents that he made a lot of effort to keep our neighborhood clean as a volunteer, which provides a better living environment for us. Realizing the mistake I made, I went to say sorry to him. And I really appreciated him for helping me learn that a person’s internal beauty is always the most valuable part instead of his appearance.",
          "explanation": null,
          "review": {
            "status": "pending"
          },
