          "materialId": "sh2017-listening-A",
          "listeningText": "，并在答题纸上填涂相应的字母代号。每个句子念两遍。\nJerry, look at your room. Could you clean it up, please?\nShe had to rest at home because of her broken leg.\nTom’s hobby is climbing mountains at weekends.\nDoes he have a habit of drinking coffee while reading?\nIt is relaxing to lie on the beach in such lovely weather.\nYou’d better not use your mobile phone when you drive.\n\n根据你听到的对话和问题选出最恰当的答案，并在答题纸上填涂相应的字母代号。对话和问题都念两遍。\nM: I’d like to paint our bedroom blue. What do you think?\nW: I prefer the color white. White makes the room brighter.\n   Q: What color does the woman prefer?\nM: Hi, my name is Linda. I move in last week.\nW: Welcome, I’m Jack. I’ve lived here for two years.\nQ: How long had Jack lived here?\nM: Did Harry telephone you about his job interview?\nW: No. But he sent me an e-mail about the result.\nQ: How did Harry tell the woman about his job interview?\nW: My speech on Monday was not good enough. Can I do again, sir?\nW: Of course, but I’m busy on Wednesday and Thursday. Friday should be fine.\nQ: When will the woman probably give the speech again?\nM: I’m thinking about learning Chinese with my friends. I want to try something new.\nW: Oh, Allen. But it’s not easy to learn Chinese.\nQ: Why does Allen want to learn Chinese?\nM: I’m really looking forward to the school dance this evening.\nW: Hmm……….I don’t think I’m going. I haven’t finished my physics project.\nQ: What will the woman most probably do this evening?\nM: Good evening. We’ve booked two rooms online.\nW: May I know your name, please?\nQ: Johnson, David Johnson.\nW: Let me see………Yes! Here we are. Two double rooms for three nights, right?\nQ: Where is Mr. Johnson now?\nM: It’s convenient to shop here. The supermarket has almost everything we want.\nW: Yes, and the food is so fresh.\nM: It’s close to our house so we don’t have to drive a car.\nQ: What are the two speakers talking about?\n\n判断下列句子是否符合你听到的短文内容。 符合的用T表示，不符合的用F表示，并在答题纸还是那个填涂相应的字母代号。短文念两遍。\n\nPeter works for a fast-food restaurant. His job is to deliver food to his customers. He enjoys going to different places and meeting different people.\n        Once, he received an order from a school. A teacher had ordered 30 sets of hamburger meals. As Peter wasn’t able to deliver them all by himself, he make the trip with a partner. When they reached the school, the teacher greeted them at the school gate, and asked for their help to bring the hamburger meals to the classroom.\n       When Peter got there, he saw 30 students waiting eagerly for their food. As soon as they saw Peter and his partner, they knew that their food had arrived and cheered loudly. After a talk with the teacher, Peter knew that a singing competition would start the next day. The teacher had provided extra help for the students the whole day. The students had practiced so hard that the teacher decided to encourage them by ordering the hamburger meals.\n       In the past two years, Peter has experienced many happy moments when serving customers like these.\n\n听对话， 完成下列内容。 对话念两遍。\n\nD: Jessica, we’re been waiting for you!\nJ: Sorry, I’m late for dinner, dad. I was looking at the website for a great organization called Living Green.\nD: Living Green? What does that mean? I don’t even like that colour.\nL: It means taking responsibility for protecting the earth. We had a guest speaker today in the science class, and he mentioned some simple ways to reduce our energy use and protected the earth.\nD: Like what?\nJ: OK, well, first of all, he said we should cut down on driving. So we’d better walk, ride bicycle , or take public transportation.\nD: I would do those things if I could.\nJ: Another idea was to turn off unnecessary lights. Look at this house------lights on in every room! He also advised us to wash our clothes in cold water.\nD: Cool! I never realized how simple it could be to ………What did you call it? Live Green?\nJ: Yeah! The speaker said that if everyone did even one of these things every day, it would do a lot to reduce global warming.\nD: I agree. That will also save money on the electric bill.",
