          "review": {
            "status": "pending"
          },
          "passage": "The following are the posts in an Internet chat room. In this chat room, parents talk about some of the problems they have with their children.\nAsk4advice\nMarisa: Is it ever OK to lie to a child? My 10-year-old son plays soccer. He's not very good, but he loves it. Yesterday he played very ___75___. When he finished the game, he asked, ‘Did I play well?’ I said, ‘Yes! You're a great soccer player!’ Did I do the right thing?\nBay212: Yes, you did the right thing. White lies are a(n) ___76___ part of life. Sometimes you have to tell lies that do no harm. Your purpose was to make him feel good. Now he's ready to play soccer again.\nBernie: I don't think there is ever a good reason to lie to our children. Children learn honesty from the ___77___ they see. As parents, we should be honest in order to teach honesty to our children. Every lie requires five more lies. If you keep hiding truth from them, they will not ___78___ you. They will not respect you. Honesty is the first step to a good parent-child relationship.\nMissy: You lied to make your son feel better, but you ___79___ a good chance to teach him a life lesson. People should work hard for what they want. Maybe next time you can say, ‘No, you didn't play well today. Great soccer players practise a lot. Let's go and practise.’ The truth will make him ___80___ and a good soccer player.\nParviz: Parents should be honest to their children, but they don't have to tell the whole truth. Next time when your son asks, ‘Did I play well?’ you can say, ‘What do you think?’ Then your son can tell you what he thinks. That way, everything you say is true, and you avoid truth that hurts.",
