          "stem": "What is thewriter’s question in LetterA？",
          "answer": "Why fill up all this  free time with housework？",
          "explanation": null,
          "review": {
            "status": "pending"
          },
          "passage": "（根据以下内容回答问题）（12分）\nLetter A\nYoung people arealways told that they should make the most of their time，that they willnever be as free again So，my question is-why fill up all this free timewith housework？Parents expect their children to get good grades，be good atsports，and be popular with other kids．\nHowever，there is not enough time inthe day to do these things and then do housework as well．It's not fair toexpect teenagers to give up their precious time to do boringhousework．Parents and children both have jobs．Parents'jobs are in theworkplace．Their children's jobs are at school．\nThe only difference isthat parents get paid and children don't．Parents say that they make theirkids do housework to teach them responsibility．But this is just atrick．Parents trick their kids into doing housework because they arelazy．\nYours，\nOverloaded\nLetter B\nBothparents and children have jobs．The parent's job is to go to work to earnmoney．The child's job is to go to school．But we all get huggry．Someone hasto cook the meals and clean up afterward．We all wear clothes that getdirty．Someone has to wash them，iron them，and put \nthem away．Chlidren workfrom 9 until 4．Parents work from 8 until 6．Sure，after 4 o'clock，childrenhave homework．But after 6，parents have homework too．They have to do theshopping，go to the bank，pay the bills，and help their kids with their ownhomework!\nI think it's only fair that teenagers help out a bit athome．They might not like it，but it's good for \nthem．It teaches them how tolook after themselves．This is really usef\nul when （93）      ．\nSincerely，\nOverworked",
