          "passage": "You can reach almost any goal if you want to—but sometimes it takes great efforts to realize your dream.\nThat was quite true for me.When I was 17 years old,I broke my father's 　[[u]]80[[/u]]　.He had saved enough from an average income to send me to college to become a lawyer.Three months later I was home telling him that I had left college—and for the first time I saw him　[[u]]81[[/u]]　.“Son,I'm always going to love you even though you'll never achieve anything,”he said with tears(眼泪)in his eyes. \nWhen I walked out of that room,I was burning with something within my body.Not everyone has the chance to feel it.I did not just want to　[[u]]82[[/u]]　—I had to. \nBut I couldn't see how to do it and all the time my father's words were in my mind.I became a salesperson.It was not　[[u]]83[[/u]]　because I knew almost nothing about marketing.Then a man introduced me to the Edwards training course.I went and learned a lot of useful 　[[u]]84[[/u]]　.I tried my best to put them to work.Soon after that,I started tasting the sweet fruits of success for the first time. \nSome time later,I told the manager of my company that I would like to meet with Mr.Edwards.They arranged it for me.When the day came,I told him,“Mr.Edwards,my goal is to be able to train people just as you trained me.”　[[u]]85[[/u]]　,he agreed to let me try. \nAll that came true because I set goals to make it happen.Sticking to the goal was the most important.",
